import { test, expect } from "../support";

test.describe("Email Composer", () => {
	const test_user = "test_email_composer@example.com";

	test.beforeAll(async ({ admin }) => {
		await admin.insert_doc(
			"User",
			{
				email: test_user,
				first_name: "Test Email Composer",
				language: "de",
				send_welcome_email: 0,
			},
			true
		);
	});

	test("picks print language from the document, not the system language", async ({ page }) => {
		await page.goto(`/desk/user/${test_user}`);
		await expect.poll(() => page.evaluate(() => window.cur_frm?.doc?.language)).toBe("de");

		await page.evaluate(() => {
			new frappe.views.CommunicationComposer({ frm: cur_frm, doc: cur_frm.doc });
		});

		await expect(page.locator(".email-composer-modal .modal-dialog")).toBeVisible();
		await expect
			.poll(() => page.evaluate(() => window.cur_dialog?.get_value("print_language")))
			.toBe("de");
	});
});

import { test, expect } from "../support";
import { shown_dialog } from "../support/shown_dialog";

// The first get_values() refreshes a mandatory input whose model value is still empty, which
// clears the typed text. A primary action that reads the dialog again sees an empty field.
async function type_without_change(dialog, fieldname, value) {
	await dialog.evaluate(
		(d, [fieldname, value]) => d.fields_dict[fieldname].$input.val(value),
		[fieldname, value]
	);
}

test.describe("Dialog primary action", () => {
	test.beforeEach(async ({ page, desk }) => {
		await page.goto("/desk/website");
		await desk.ready();
	});

	test("frappe.prompt passes typed values to the callback", async ({ page }) => {
		const dialog = await page.evaluateHandle(() =>
			frappe.prompt(
				{ label: "Title", fieldname: "title", fieldtype: "Data", reqd: 1 },
				(v) => {
					window.prompt_values = v;
				}
			)
		);
		await shown_dialog(dialog);
		await type_without_change(dialog, "title", "Prompt Title");
		await dialog.evaluate((d) => d.get_primary_btn().click());

		await expect
			.poll(() => page.evaluate(() => window.prompt_values))
			.toEqual({
				title: "Prompt Title",
			});
	});

	test("frappe.prompt still blocks an empty mandatory field", async ({ page }) => {
		const dialog = await page.evaluateHandle(() =>
			frappe.prompt(
				{ label: "Title", fieldname: "title", fieldtype: "Data", reqd: 1 },
				(v) => {
					window.prompt_values = v;
				}
			)
		);
		await shown_dialog(dialog);
		await dialog.evaluate((d) => d.get_primary_btn().click());

		await expect(page.locator(".msgprint-dialog")).toContainText("Title");
		expect(await page.evaluate(() => window.prompt_values)).toBeUndefined();
	});

	test("quick entry keeps typed values", async ({ page }) => {
		const dialog = await page.evaluateHandle(() =>
			frappe.ui.form.make_quick_entry(
				"Note",
				(doc) => {
					window.quick_entry_doc = doc;
				},
				null,
				null,
				true,
				true
			)
		);
		await shown_dialog(dialog);
		await type_without_change(dialog, "title", "Quick Entry Title");
		await dialog.evaluate((d) => d.get_primary_btn().click());

		await expect
			.poll(() => page.evaluate(() => window.quick_entry_doc?.title))
			.toBe("Quick Entry Title");
	});
});

import { test, expect, TEST_USER } from "../support";

test.describe.skip("Permissions API", () => {
	const set_system_manager = (admin, action) =>
		admin.call("frappe.tests.ui_test_helpers.add_remove_role", {
			action,
			user: TEST_USER,
			role: "System Manager",
		});

	test.beforeAll(async ({ admin }) => {
		await set_system_manager(admin, "remove");
	});

	test.afterAll(async ({ admin }) => {
		await set_system_manager(admin, "add");
	});

	test("Checks permissions via `has_perm` for Kanban Board DocType", async ({ page }) => {
		await page.goto("/desk/kanban-board/view/list");
		const perms = await page.evaluate(
			() =>
				new Promise((resolve) =>
					frappe.model.with_doctype("Kanban Board", () =>
						resolve({
							read: frappe.perm.has_perm("Kanban Board", 0, "read"),
							write: frappe.perm.has_perm("Kanban Board", 0, "write"),
							print: frappe.perm.has_perm("Kanban Board", 0, "print"),
						})
					)
				)
		);
		expect(perms).toEqual({ read: true, write: true, print: false });
	});

	test("Checks permissions via `get_perm` for Kanban Board DocType", async ({ page }) => {
		await page.goto("/desk/kanban-board/view/list");
		const perms = await page.evaluate(
			() =>
				new Promise((resolve) =>
					frappe.model.with_doctype("Kanban Board", () =>
						resolve(frappe.perm.get_perm("Kanban Board"))
					)
				)
		);
		expect(perms.read).toBe(true);
		expect(perms.write).toBe(true);
		expect(perms.rights_without_if_owner).toContain("read");
	});
});

test.describe("Permissions before a doctype's meta is loaded", () => {
	test("Resolves delete for ToDo before its meta is loaded", async ({ page, desk }) => {
		await page.goto("/desk");
		await desk.ready();

		const before = await page.evaluate(() => {
			delete locals.DocType["ToDo"];
			delete frappe.perm.doctype_perm["ToDo"];

			return {
				has_meta: Boolean(frappe.get_meta("ToDo")),
				can_delete: frappe.perm.has_perm("ToDo", 0, "delete"),
			};
		});
		expect(before).toEqual({ has_meta: false, can_delete: true });

		const after = await page.evaluate(
			() =>
				new Promise((resolve) =>
					frappe.model.with_doctype("ToDo", () =>
						resolve({
							has_meta: Boolean(frappe.get_meta("ToDo")),
							can_delete: frappe.perm.has_perm("ToDo", 0, "delete"),
						})
					)
				)
		);
		expect(after).toEqual({ has_meta: true, can_delete: true });
	});
});

import { test, expect } from "../support";

test.describe("User-permission aware defaults", () => {
	// Regression: `frappe.defaults.get_user_defaults` must never return a default value
	// (e.g. the global default company) that the user is not permitted for, otherwise the
	// value gets auto-set on new documents and later fails the read/permission check.
	test("get_user_defaults drops values not permitted to the user", async ({ page, desk }) => {
		await page.goto("/desk");
		await desk.ready();

		const result = await page.evaluate(() => {
			const defaults = frappe.boot.user.defaults;
			const saved_defaults = {
				company: defaults["company"],
				Company: defaults["Company"],
			};
			const saved_perms = frappe.defaults._user_permissions;
			const result = {};

			try {
				// user is restricted to "_Allowed Co" but their (global) default is "_Denied Co"
				delete defaults["Company"];
				defaults["company"] = "_Denied Co";
				frappe.defaults._user_permissions = {
					Company: [{ doc: "_Allowed Co", applicable_for: null, is_default: 0 }],
				};
				result.denied = frappe.defaults.get_user_defaults("Company");

				defaults["company"] = "_Allowed Co";
				result.allowed = frappe.defaults.get_user_defaults("Company");

				frappe.defaults._user_permissions = {};
				defaults["company"] = "_Denied Co";
				result.unrestricted = frappe.defaults.get_user_defaults("Company");
			} finally {
				defaults["company"] = saved_defaults.company;
				defaults["Company"] = saved_defaults.Company;
				frappe.defaults._user_permissions = saved_perms;
			}
			return result;
		});

		// the disallowed default must be filtered out
		expect(result.denied).not.toContain("_Denied Co");
		// a permitted default is retained
		expect(result.allowed).toContain("_Allowed Co");
		// with no user permission on Company, the default is kept (nothing to restrict)
		expect(result.unrestricted).toContain("_Denied Co");
	});
});

import base64
from imaplib import IMAP4
from poplib import POP3
from smtplib import SMTP

import frappe


class Oauth:
	def __init__(
		self,
		conn: IMAP4 | POP3 | SMTP,
		email_account: str,
		email: str,
		access_token: str,
		mechanism: str = "XOAUTH2",
	) -> None:
		self.email_account = email_account
		self.email = email
		self._mechanism = mechanism
		self._conn = conn
		self._access_token = access_token

		self._validate()

	def _validate(self) -> None:
		if not self._access_token:
			frappe.throw(
				frappe._("Please Authorize OAuth for Email Account {}").format(self.email_account),
				title=frappe._("OAuth Error"),
			)

	@property
	def _auth_string(self) -> str:
		return f"user={self.email}\1auth=Bearer {self._access_token}\1\1"

	def connect(self) -> None:
		try:
			if isinstance(self._conn, POP3):
				self._connect_pop()

			elif isinstance(self._conn, IMAP4):
				self._connect_imap()

			else:
				# SMTP
				self._connect_smtp()

		except Exception:
			frappe.log_error(
				"Email Connection Error - Authentication Failed",
				reference_doctype="Email Account",
				reference_name=self.email_account,
			)
			# raising a bare exception here as we have a lot of exception handling present
			# where the connect method is called from - hence just logging and raising.
			raise

	def _connect_pop(self) -> None:
		# NOTE: poplib doesn't have AUTH command implementation
		res = self._conn._shortcmd(
			"AUTH {} {}".format(
				self._mechanism, base64.b64encode(bytes(self._auth_string, "utf-8")).decode("utf-8")
			)
		)

		if not res.startswith(b"+OK"):
			frappe.log_error(
				title="POP3 OAuth Authentication Failed",
				message=f"Response: {res}",
				reference_doctype="Email Account",
				reference_name=self.email_account,
			)
			frappe.throw(
				frappe._("POP3 OAuth authentication failed for Email Account {0}").format(self.email_account),
				frappe.AuthenticationError,
			)

	def _connect_imap(self) -> None:
		self._conn.authenticate(self._mechanism, lambda x: self._auth_string)

	def _connect_smtp(self) -> None:
		self._conn.auth(self._mechanism, lambda x: self._auth_string, initial_response_ok=False)

import os
import sys

import click

import frappe
from frappe.database.db_manager import DbManager


def get_mariadb_variables():
	return frappe._dict(frappe.db.sql("show variables"))


def get_mariadb_version(version_string: str = ""):
	# MariaDB classifies their versions as Major (1st and 2nd number), and Minor (3rd number)
	# Example: Version 10.3.13 is Major Version = 10.3, Minor Version = 13
	version_string = version_string or get_mariadb_variables().get("version")
	version = version_string.split("-", 1)[0]
	return version.rsplit(".", 1)


def setup_database(force, verbose, mariadb_user_host_login_scope=None):
	frappe.local.session = frappe._dict({"user": "Administrator"})

	db_user = frappe.conf.db_user
	db_name = frappe.local.conf.db_name
	root_conn = get_root_connection()
	dbman = DbManager(root_conn)
	dbman_kwargs = {}

	if mariadb_user_host_login_scope is not None:
		dbman_kwargs["host"] = mariadb_user_host_login_scope

	dbman.create_user(db_user, frappe.conf.db_password, **dbman_kwargs)
	if verbose:
		print(f"Created or updated user {db_user}")

	if force or (db_name not in dbman.get_database_list()):
		dbman.drop_database(db_name)
	else:
		print(f"Database {db_name} already exists, please drop it manually or pass `--force`.")
		sys.exit(1)

	dbman.create_database(db_name)
	if verbose:
		print("Created database {}".format(db_name))

	dbman.grant_all_privileges(db_name, db_user, **dbman_kwargs)
	dbman.flush_privileges()
	if verbose:
		print(f"Granted privileges to user {db_user} and database {db_name}")

	# close root connection
	root_conn.close()


def drop_user_and_database(
	db_name,
	db_user,
):
	frappe.local.db = get_root_connection()
	dbman = DbManager(frappe.local.db)
	dbman.drop_database(db_name)
	dbman.delete_user(db_user, host="%")
	dbman.delete_user(db_user)


def bootstrap_database(verbose, source_sql=None):
	import sys

	frappe.connect()
	check_compatible_versions()

	import_db_from_sql(source_sql, verbose)

	frappe.connect()
	if "tabDefaultValue" not in frappe.db.get_tables(cached=False):
		from click import secho

		secho(
			"Table 'tabDefaultValue' missing in the restored site. "
			"This happens when the backup fails to restore. Please check that the file is valid\n"
			"Do go through the above output to check the exact error message from MariaDB",
			fg="red",
		)
		sys.exit(1)


def import_db_from_sql(source_sql=None, verbose=False):
	if verbose:
		print("Starting database import...")
	db_name = frappe.conf.db_name
	if not source_sql:
		source_sql = os.path.join(os.path.dirname(__file__), "framework_mariadb.sql")
	DbManager(frappe.local.db).restore_database(
		verbose, db_name, source_sql, frappe.conf.db_user, frappe.conf.db_password
	)
	if verbose:
		print("Imported from database {}".format(source_sql))


def check_compatible_versions():
	try:
		version = get_mariadb_version()
		version_tuple = tuple(int(v) for v in version[0].split("."))

		if version_tuple < (10, 6):
			click.secho(
				f"Warning: MariaDB version {version} is older than 10.6 which is not supported by Frappe",
				fg="yellow",
			)
		elif version_tuple > (11, 8):
			click.secho(
				f"Warning: MariaDB version {version} is newer than 11.8 which is not yet tested with Frappe Framework.",
				fg="yellow",
			)
	except Exception:
		click.secho(
			"MariaDB version compatibility checks failed, make sure you're running a supported version.",
			fg="yellow",
		)


def get_root_connection():
	if not frappe.local.flags.root_connection:
		from getpass import getpass

		if not frappe.flags.root_login:
			frappe.flags.root_login = (
				frappe.conf.get("mariadb_root_login")
				or frappe.conf.get("root_login")
				or (sys.__stdin__.isatty() and input("Enter mysql super user [root]: "))
				or "root"
			)

		if not frappe.flags.root_password:
			frappe.flags.root_password = (
				frappe.conf.get("mariadb_root_password")
				or frappe.conf.get("root_password")
				or getpass("MySQL root password: ")
			)

		frappe.local.flags.root_connection = frappe.database.get_db(
			socket=frappe.conf.db_socket,
			host=frappe.conf.db_host,
			port=frappe.conf.db_port,
			user=frappe.flags.root_login,
			password=frappe.flags.root_password,
			cur_db_name=None,
		)

	return frappe.local.flags.root_connection

